def length_report(words):
    lengths = list(map(len, words))
    return [lengths, sum(lengths)]

def above_average(nums):
    if not nums:
        return []
    avg = sum(nums) / len(nums)
    return list(filter(lambda n: n > avg, nums))

def peak_positions(nums):
    return [i for i, x in enumerate(nums[1:-1], start=1)
            if x > nums[i - 1] and x > nums[i + 1]]

def middle_chars(text):
    n = len(text)
    return text[(n - 1) // 2: n // 2 + 1]

def rows_are_permutations(grid):
    n = len(grid)
    return all(sorted(row) == list(range(1, n + 1)) for row in grid)

def median(nums):
    if not nums:
        return None
    ordered = sorted(nums)
    mid = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2

def is_palindrome(text):
    cleaned = text.replace(" ", "").lower()
    return "".join(reversed(cleaned)) == cleaned

def digit_list(n):
    digits = []
    while True:
        n, d = divmod(n, 10)
        digits.append(d)
        if n == 0:
            break
    return digits[::-1]

def sum_nested(data):
    total = 0
    for item in data:
        if isinstance(item, list):
            total += sum_nested(item)
        elif isinstance(item, (int, float)) and not isinstance(item, bool):
            total += item
    return total

def passed_report(names, scores):
    report = []
    for name, score in zip(names, scores):
        if score >= 50:
            report.append(f"{name}: {score}")
    return report

def ranked_totals(names, amounts):
    totals = {}
    for name, amount in zip(names, amounts):
        if name in totals:
            totals[name] += amount
        else:
            totals[name] = amount
    ranked = sorted(totals.items(), key=lambda pair: (-pair[1], pair[0]))
    return [[name, total] for name, total in ranked]

def days_to_goal(daily_steps, goal):
    if goal <= 0:
        return 0
    for day in range(1, len(daily_steps) + 1):
        if sum(daily_steps[:day]) >= goal:
            return day
    return -1

def strong_teams(records, limit):
    groups = {}
    for team, points in records:
        groups.setdefault(team, []).append(points)
    result = []
    for team in sorted(groups):
        total = sum(groups[team])
        if total >= limit:
            result.append([team, total])
    return result

def best_scores(scores, n):
    valid = [s for s in scores if s >= 0]
    return sorted(valid, reverse=True)[:n]

def names_by_grade(records):
    by_grade = {}
    for name, grade in records:
        if grade not in by_grade:
            by_grade[grade] = []
        by_grade[grade].append(name)
    result = []
    for grade in sorted(by_grade, reverse=True):
        result.extend(sorted(by_grade[grade]))
    return result

def parse_whole_numbers(texts):
    cleaned = list(map(str.strip, texts))
    result = []
    for text in cleaned:
        if text.lstrip("-").isdigit():
            result.append(int(text))
    return result

def words_by_length(sentence):
    words = sentence.split()
    lengths = list(map(len, words))
    table = {}
    for word, n in zip(words, lengths):
        if n not in table:
            table[n] = []
        if word not in table[n]:
            table[n].append(word)
    return [[n, table[n]] for n in sorted(table)]

def tidy_emails(items):
    result = []
    for item in filter(lambda value: isinstance(value, str), items):
        if item.count("@") == 1 and not item.startswith("@") and not item.endswith("@"):
            result.append(item.lower())
    return result

def big_unique(nums, limit):
    seen = set()
    result = []
    for n in filter(lambda x: x > limit, nums):
        if n not in seen:
            seen.add(n)
            result.append(n)
    return result

def change_points(readings):
    points = []
    for i, value in enumerate(readings):
        if i > 0 and value != readings[i - 1]:
            points.append(i)
    return points

def repeated_items(items):
    counts = {}
    last = {}
    for i, item in enumerate(items):
        counts[item] = counts.get(item, 0) + 1
        last[item] = i
    result = [[item, last[item]] for item in last if counts[item] > 1]
    return sorted(result, key=lambda pair: pair[1])

def lines_too_long(lines, width):
    too_long = []
    for number in range(1, len(lines) + 1):
        if len(lines[number - 1]) > width:
            too_long.append(number)
    return too_long

def common_prefix(words):
    if len(words) == 0:
        return ""
    prefix = words[0]
    for word in words[1:]:
        while not word.startswith(prefix):
            prefix = prefix[:-1]
    return prefix

def hottest_day(temps):
    if not temps:
        return -1
    highest = max(temps)
    for i, t in enumerate(temps):
        if t == highest:
            return i

def best_scores(records):
    best = {}
    for player, score in records:
        if player not in best:
            best[player] = score
        else:
            best[player] = max(best[player], score)
    order = sorted(best, key=lambda p: (-best[p], p))
    return [[p, best[p]] for p in order]

def cheapest_in_stock(items):
    options = []
    for name, price, stock in items:
        if stock > 0:
            options.append([price, name])
    if not options:
        return ""
    return min(options)[1]

def smallest_gap(nums):
    if len(nums) < 2:
        return None
    gaps = []
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            gaps.append(abs(nums[i] - nums[j]))
    return min(gaps)

def leap_years(start, end):
    years = []
    for year in range(start, end + 1):
        if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
            years.append(year)
    return years

def primes_up_to(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, n + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(n + 1) if is_prime[i]]

def count_flagged(sentences, forbidden):
    flagged = 0
    for sentence in sentences:
        words = sentence.lower().split()
        if any(word in forbidden for word in words):
            flagged += 1
    return flagged

def has_route(roads, start, goal):
    if not any(start in road for road in roads):
        return start == goal
    neighbours = {}
    for a, b in roads:
        neighbours.setdefault(a, []).append(b)
        neighbours.setdefault(b, []).append(a)
    seen = set()
    stack = [start]
    while stack:
        city = stack.pop()
        if city == goal:
            return True
        if city not in seen:
            seen.add(city)
            for other in neighbours.get(city, []):
                stack.append(other)
    return False

def count_ascending_rows(table):
    count = 0
    for row in table:
        if all(row[i] < row[i + 1] for i in range(len(row) - 1)):
            count += 1
    return count

def balanced_brackets(text):
    if not all(ch in "()[]{}" for ch in text):
        return False
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)
    return not stack

def palindromes(words):
    result = []
    for word in words:
        lower = word.lower()
        if list(lower) == list(reversed(lower)):
            result.append(word)
    return result

def days_until_warmer(temps):
    answer = [0] * len(temps)
    stack = []
    for i in reversed(range(len(temps))):
        while stack and temps[stack[-1]] <= temps[i]:
            stack.pop()
        if stack:
            answer[i] = stack[-1] - i
        stack.append(i)
    return answer

def closest_sum(nums, target):
    best = None
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            total = nums[i] + nums[j]
            if best is None or abs(total - target) < abs(best - target):
                best = total
    return best

def big_swings(temps, limit):
    count = 0
    for i in range(1, len(temps)):
        if abs(temps[i] - temps[i - 1]) > limit:
            count += 1
    return count

def duration_text(seconds):
    minutes, secs = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    parts = []
    for value, unit in [[hours, "h"], [minutes, "min"], [secs, "s"]]:
        if value > 0:
            parts.append(f"{value}{unit}")
    if not parts:
        return "0s"
    return " ".join(parts)

def make_change(amount, coins):
    counts = {}
    for coin in sorted(coins, key=lambda c: -c):
        count, amount = divmod(amount, coin)
        if count > 0:
            counts[coin] = count
    if amount != 0:
        return []
    return [[coin, counts[coin]] for coin in counts]

def nearest_ten(prices):
    result = []
    for price in prices:
        rounded = round(price, -1)
        if rounded < 10:
            rounded = 10
        result.append(rounded)
    return result

def bucket_counts(values):
    counts = {}
    for v in values:
        if v < 0:
            continue
        bucket = round(v, -1)
        counts[bucket] = counts.get(bucket, 0) + 1
    return [[bucket, counts[bucket]] for bucket in sorted(counts)]

def count_kinds(values):
    numbers = 0
    texts = 0
    others = 0
    for v in values:
        if isinstance(v, bool):
            others += 1
        elif isinstance(v, (int, float)):
            numbers += 1
        elif isinstance(v, str):
            texts += 1
        else:
            others += 1
    return [numbers, texts, others]

def collect_strings(data):
    found = []
    for item in data:
        if isinstance(item, str):
            found.append(item)
        elif isinstance(item, list):
            found.extend(collect_strings(item))
    return sorted(set(found), key=lambda s: (len(s), s))
